//! Adaptive network size classification for gossip protocol tuning

use crate::get_average_peer_count;

/// Adaptive network size classification based on average peer count.
///
/// Used to configure gossipsub mesh parameters appropriately for network conditions.
/// Smaller networks use aggressive flooding; larger networks use lazy gossip.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum NetworkSize {
    /// 0-3 peers: Use `flood_publish`, aggressive heartbeat
    Small,
    /// 4-15 peers: Balanced mesh topology
    Medium,
    /// 16+ peers: Larger mesh, lazy gossip
    Large,
}

impl std::fmt::Display for NetworkSize {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(match self {
            Self::Small => "Small",
            Self::Medium => "Medium",
            Self::Large => "Large",
        })
    }
}

impl NetworkSize {
    /// Classify network size based on average peer count.
    ///
    /// # Arguments
    /// * `avg` - Average number of concurrent peers from historical data
    ///
    /// # Returns
    /// `NetworkSize` classification for configuring gossipsub behavior
    #[must_use]
    pub const fn from_peer_count(avg: f64) -> Self {
        // SAFETY: average peer counts are small non-negative values, so the
        // f64 -> i32 conversion cannot truncate meaningful data.
        #[allow(clippy::as_conversions, clippy::cast_possible_truncation)]
        let avg = avg as i32;
        match avg {
            0..=3 => Self::Small,
            4..=15 => Self::Medium,
            _ => Self::Large,
        }
    }
}

/// Determine the current network size classification.
///
/// Calculates the average peer count from historical data and returns
/// a `NetworkSize` classification for configuring gossipsub behavior.
///
/// # Returns
/// The current `NetworkSize` (Small, Medium, or Large)
///
/// # Errors
/// Returns an error if the historical peer count cannot be read from the
/// database.
pub fn get_network_size() -> color_eyre::Result<NetworkSize> {
    let avg = get_average_peer_count()?;
    Ok(NetworkSize::from_peer_count(avg))
}

