/// Render a full TUI frame
pub fn render_frame(f: &mut ratatui::Frame, state: &mut TuiRenderState) {
    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(1),
            Constraint::Min(0),
            Constraint::Length(5),
            Constraint::Length(1),
            Constraint::Length(1),
        ])
        .split(f.area());

    let default_rect = Rect::default();
    let tab_area = chunks.first().unwrap_or(&default_rect);
    let content_area = chunks.get(1).unwrap_or(&default_rect);
    let input_area = chunks.get(2).unwrap_or(&default_rect);
    let shortcut_area = chunks.get(3).unwrap_or(&default_rect);
    let status_area = chunks.get(4).unwrap_or(&default_rect);

    render_tabs(f, *tab_area, state);

    let tab_content = get_tab_content(state);
    render_tab_content(f, *content_area, &tab_content, state);

    render_input_section(f, *input_area, state, &tab_content);
    render_shortcuts(f, *shortcut_area, &tab_content, state.kitty_keyboard_active);
    render_status_bar(f, *status_area, state);

    if let Some(ref text) = state.popup {
        render_popup(f, text.clone());
    }
}

/// Render the tab bar
pub fn render_tabs(f: &mut ratatui::Frame, area: Rect, state: &TuiRenderState) {
    let titles: Vec<&str> = state
        .tab_titles
        .iter()
        .map(std::string::String::as_str)
        .collect();
    let tabs = Tabs::new(titles)
        .style(Style::default().fg(Color::Cyan))
        .select(state.active_tab)
        .highlight_style(Style::default().add_modifier(Modifier::REVERSED));
    f.render_widget(tabs, area);
}

/// Render tab content
pub fn render_tab_content(
    f: &mut ratatui::Frame,
    area: Rect,
    tab_content: &TabContent,
    state: &mut TuiRenderState,
) {
    match tab_content {
        TabContent::Chat => render_chat_content(f, area, state),
        TabContent::Peers => render_peers_content(f, area, state),
        TabContent::Groups => render_groups_content(f, area, state),
        TabContent::GroupChat(group_id) => render_group_chat_content(f, area, group_id, state),
        TabContent::Direct(peer_id) => render_dm_content(f, area, peer_id, state),
        TabContent::Log => render_log_content(f, area, state),
        TabContent::Settings => render_settings_content(f, area, state),
        TabContent::PeerInfo(peer_id) => render_peer_info_content(f, area, peer_id, state),
    }
}

/// Shared bordered list/paragraph block with the given title.
pub(crate) fn bordered_block(title: String) -> Block<'static> {
    Block::default().title(title).borders(Borders::ALL)
}

/// Render input section
pub fn render_input_section(
    f: &mut ratatui::Frame,
    area: Rect,
    state: &TuiRenderState,
    tab_content: &TabContent,
) {
    let title = if state.editing_nickname {
        format!("Edit Nickname ({})", short_peer_id(&state.nickname_peer_id))
    } else {
        "Input".to_string()
    };

    let input_block = Block::default().title(title).borders(Borders::ALL);

    if tab_content.is_input_enabled() || state.editing_nickname {
        let inner_area = input_block.inner(area);
        f.render_widget(input_block, area);
        let input = Paragraph::new(state.input_text.as_str());
        f.render_widget(input, inner_area);
    } else {
        f.render_widget(input_block, area);
    }
}

/// Shortcut hint line for the given tab. Peer-Info bindings are documented only
/// on tabs where they are active: Ctrl+I (kitty) and Ctrl+P (universal) on a
/// Direct/DM tab, `i` on Peers.
#[must_use]
pub const fn shortcuts_text(tab_content: &TabContent, kitty: bool) -> &'static str {
    match tab_content {
        TabContent::Peers => {
            "Tab: next | Up/Down: select | Enter: open DM | i: Peer Info | F12: mouse | Ctrl+Q: quit"
        }
        TabContent::Groups => {
            "Tab: next | Up/Down: select | Enter: open chat | g: create/join | F12: mouse | Ctrl+Q: quit"
        }
        TabContent::Direct(_) if kitty => {
            "Tab: next | Ctrl+I/Ctrl+P: Peer Info | PgUp/PgDn: scroll | Home/End: jump | Enter: send | F12: mouse | Ctrl+Q: quit"
        }
        TabContent::Direct(_) => {
            "Tab: next | Ctrl+P: Peer Info | PgUp/PgDn: scroll | Home/End: jump | Enter: send | F12: mouse | Ctrl+Q: quit"
        }
        _ => {
            "Tab: next | PgUp/PgDn: scroll | Home/End: jump | Enter: send | F12: mouse | Ctrl+Q: quit"
        }
    }
}

/// Render shortcuts help, tailored to the active tab
pub fn render_shortcuts(f: &mut ratatui::Frame, area: Rect, tab_content: &TabContent, kitty: bool) {
    let shortcuts = Paragraph::new(shortcuts_text(tab_content, kitty));
    f.render_widget(shortcuts, area);
}

/// Render status bar
pub fn render_status_bar(f: &mut ratatui::Frame, area: Rect, state: &TuiRenderState) {
    let mouse = if state.mouse_capture { "ON" } else { "OFF" };
    let conn = if state.connected {
        "Connected"
    } else {
        "Disconnected"
    };
    let status = Paragraph::new(format!("{conn} [Mouse: {mouse}]"));
    f.render_widget(status, area);
}

/// Render popup
#[allow(
    clippy::as_conversions,
    clippy::cast_possible_truncation,
    clippy::cast_sign_loss,
    clippy::arithmetic_side_effects
)]
pub fn render_popup(f: &mut ratatui::Frame, text: String) {
    let area = f.area();
    let w = (f32::from(area.width) * 0.70) as u16;
    let h = (f32::from(area.height) * 0.40) as u16;
    let popup = Rect {
        x: area.x + (area.width.saturating_sub(w)) / 2,
        y: area.y + (area.height.saturating_sub(h)) / 2,
        width: w.max(20).min(area.width),
        height: h.max(6).min(area.height),
    };

    f.render_widget(Clear, popup);
    let p = Paragraph::new(text)
        .block(
            Block::default()
                .title("Details")
                .borders(Borders::ALL)
                .style(Style::default().bg(Color::Black)),
        )
        .alignment(Alignment::Left)
        .wrap(Wrap { trim: false });
    f.render_widget(p, popup);
}

//! Peer-info tab rendering (mirrors Flutter's `PeerInfoScreen`).

use crate::fmt::short_peer_id;
use crate::tui_render_state::TuiRenderState;
use ratatui::{
    layout::Rect,
    widgets::{Block, Borders, Paragraph, Wrap},
};

/// Render the Peer Info tab (mirrors the Flutter `PeerInfoScreen`).
pub fn render_peer_info_content(
    f: &mut ratatui::Frame,
    area: Rect,
    peer_id: &str,
    state: &TuiRenderState,
) {
    let display = crate::get_peer_display_name(peer_id).unwrap_or_else(|_| short_peer_id(peer_id));
    let local = state.local_nicknames.get(peer_id);
    let received = state.received_nicknames.get(peer_id);

    let (origin, detail) = if local.is_some() {
        ("Local nickname", "You set this nickname for the peer.")
    } else if received.is_some() {
        (
            "Received nickname",
            "Announced by the peer. (Receipt time is not tracked.)",
        )
    } else {
        (
            "Generated petname",
            "No nickname was known, so a petname was assigned locally.",
        )
    };

    let (first_seen, last_seen) = state
        .peers
        .iter()
        .find(|p| p.peer_id == peer_id)
        .map_or_else(
            || ("unknown".to_string(), "unknown".to_string()),
            |p| (p.first_seen.clone(), p.last_seen.clone()),
        );

    let mut lines: Vec<String> = Vec::new();
    lines.push(format!("Peer: {display}"));
    lines.push(format!("Peer ID: {peer_id}"));
    lines.push(format!("Origin: {origin}"));
    lines.push(format!("  {detail}"));
    if let Some(n) = local {
        lines.push(format!("Local nickname: {n}"));
    }
    if let Some(n) = received {
        lines.push(format!("Received nickname: {n}"));
    }
    lines.push(format!("First seen: {first_seen}"));
    lines.push(format!("Last seen: {last_seen}"));
    lines.push("Press Enter to open direct message".to_string());

    let para = Paragraph::new(lines.join("\n"))
        .block(Block::default().title("Peer Info").borders(Borders::ALL))
        .wrap(Wrap { trim: false });
    f.render_widget(para, area);
}

//! Peers-table rendering (stateful `Table` + sort hint).

use crate::tui_helpers::{
    peer_table_column_widths, peer_table_header_labels, peer_table_rows_range,
    peer_table_visible_range,
};
use crate::tui_render_state::TuiRenderState;
use ratatui::{
    layout::{Constraint, Direction, Layout, Rect},
    style::{Color, Modifier, Style},
    widgets::{Block, Borders, Cell, Paragraph, Row, Table, TableState},
};

/// Render peer list with selection support
pub fn render_peers_content(f: &mut ratatui::Frame, area: Rect, state: &TuiRenderState) {
    // The table body is content_height - 1 (hint) - 2 (borders) - 1 (header)
    // rows tall; a stateful `TableState` scrolls the viewport to keep the
    // selected row visible, so PageUp/PageDown step the selection by a page.
    let page_height = usize::from(area.height.saturating_sub(4)).max(1);
    let total = state.peers.len();
    let selected = (total > 0).then(|| state.peer_selection.min(total.saturating_sub(1)));
    let (start, end) =
        peer_table_visible_range(state.peer_table_offset, selected, total, page_height);

    // Materialize only the visible window: display-name lookups are the
    // expensive per-frame cost, so paged rendering stays O(page) no matter how
    // many peers are known.
    let rows = peer_table_rows_range(
        &state.peers,
        &state.dm_messages,
        &state.broadcast_sent_to_peer,
        start,
        end,
    );

    let header_cells: Vec<Cell> =
        peer_table_header_labels(state.peer_sort_column, state.peer_sort_ascending)
            .into_iter()
            .map(Cell::from)
            .collect();
    let header = Row::new(header_cells).style(Style::default().add_modifier(Modifier::BOLD));

    let body: Vec<Row> = rows
        .iter()
        .map(|r| {
            let cells = [
                Cell::from(r.display_name.clone()),
                Cell::from(r.dm_count.to_string()),
                Cell::from(r.broadcast_count.to_string()),
                Cell::from(r.last_seen.clone()),
                Cell::from(r.first_seen.clone()),
            ];
            Row::new(cells)
        })
        .collect();

    let widths: Vec<Constraint> =
        peer_table_column_widths(&rows, state.peer_sort_column, state.peer_sort_ascending)
            .into_iter()
            .map(|w| Constraint::Length(u16::try_from(w).unwrap_or(u16::MAX)))
            .collect();
    let table = Table::new(body, widths)
        .header(header)
        .block(
            Block::default()
                .title(format!("Connected Peers ({total})"))
                .borders(Borders::ALL),
        )
        .row_highlight_style(Style::default().bg(Color::DarkGray));

    // Reserve the last row of the block's inner area for a sort hint.
    let inner = Layout::default()
        .direction(Direction::Vertical)
        .constraints([Constraint::Min(1), Constraint::Length(1)])
        .split(area);
    let table_area = *inner.first().unwrap_or(&area);
    let hint_area = *inner.get(1).unwrap_or(&area);

    let mut table_state = TableState::new();
    table_state.select(selected.map(|sel| sel.saturating_sub(start)));
    *table_state.offset_mut() = 0;
    f.render_stateful_widget(table, table_area, &mut table_state);

    let hint = Paragraph::new(
        "1-5 (or n/m/b/l/f): sort · o: toggle order · click header · PgUp/PgDn: page",
    )
    .style(Style::default().add_modifier(Modifier::DIM));
    f.render_widget(hint, hint_area);
}

//! Settings-tab rendering (mirrors Flutter's `_Settings` screen).

use crate::tui_render_state::TuiRenderState;
use ratatui::{
    layout::Rect,
    widgets::{Block, Borders, Paragraph, Wrap},
};

/// Format an optional epoch-seconds timestamp as a readable local datetime.
#[allow(clippy::as_conversions, clippy::cast_possible_truncation)]
fn format_lost_at(ts: Option<f64>) -> String {
    ts.and_then(|t| {
        chrono::DateTime::from_timestamp(t as i64, 0)
            .map(|dt| crate::format_peer_datetime(dt.with_timezone(&chrono::Local).naive_local()))
    })
    .unwrap_or_else(|| "—".to_string())
}

/// The most recent connection we had to report on the Settings tab: this
/// session's last disconnect if any, otherwise the known peer with the newest
/// `last_seen`. Returns `(peer_id, formatted_timestamp)`.
fn last_connected_info(state: &TuiRenderState) -> Option<(String, String)> {
    if let (Some(peer_id), Some(at)) = (&state.last_connection_peer, state.last_connection_lost) {
        return Some((peer_id.clone(), format_lost_at(Some(at))));
    }
    state
        .peers
        .iter()
        .max_by(|a, b| a.last_seen.cmp(&b.last_seen))
        .map(|p| (p.peer_id.clone(), p.last_seen.clone()))
}

/// Render the Settings tab (mirrors the Flutter `_Settings` screen).
pub fn render_settings_content(f: &mut ratatui::Frame, area: Rect, state: &TuiRenderState) {
    let connected = state.peer_count;
    let node_status = if state.node_running {
        "Running"
    } else {
        "Stopped"
    };

    let mut lines: Vec<String> = Vec::new();
    lines.push(format!(
        "Nickname: {}  (press 'n' to edit)",
        state.own_nickname
    ));
    lines.push(format!("Peer ID: {}", state.local_peer_id));
    lines.push(format!("Database: {}", state.db_url));
    lines.push(format!("Platform: {}", state.platform));
    lines.push(format!("Node: {node_status}"));
    lines.push(format!("Network name: {}", crate::CHAT_TOPIC));
    lines.push(format!("Network size: {}", state.network_size));
    lines.push(format!("Connected peers: {connected}"));
    if state.connected_peer_ids.is_empty() {
        // Only ever show "currently connected" peers. When none are connected,
        // say when we last were (this session's record, else the most recently
        // seen known peer) instead of listing stale peers as connected.
        match last_connected_info(state) {
            Some((peer_id, ts)) => {
                let display = crate::get_peer_display_name(&peer_id)
                    .unwrap_or_else(|_| crate::fmt::short_peer_id(&peer_id));
                lines.push(format!("  Last connected {ts} to peer {display}"));
            }
            None => lines.push("  —".to_string()),
        }
    } else {
        for peer_id in &state.connected_peer_ids {
            let display = crate::get_peer_display_name(peer_id)
                .unwrap_or_else(|_| crate::fmt::short_peer_id(peer_id));
            lines.push(format!("  {display}"));
        }
    }
    lines.push("Listen addresses:".to_string());
    if state.listen_addrs.is_empty() {
        lines.push("  —".to_string());
    } else {
        for addr in &state.listen_addrs {
            lines.push(format!("  {addr}"));
        }
    }

    let para = Paragraph::new(lines.join("\n"))
        .block(Block::default().title("Settings").borders(Borders::ALL))
        .wrap(Wrap { trim: false });
    f.render_widget(para, area);
}

//! TUI rendering state abstraction for testing
//!
//! This module provides a render state that can be used by both the binary
//! and integration tests. The binary uses `AppState`, tests use this abstraction.

use crate::PeerRecord;
use std::collections::{BTreeMap, HashMap, VecDeque};

/// Minimum state needed to render a TUI frame
#[allow(clippy::struct_excessive_bools)]
#[derive(Clone, Debug)]
pub struct TuiRenderState {
    /// Names of tabs for display (Chat, Peers, Log, plus DM tabs)
    pub tab_titles: Vec<String>,
    /// Currently active tab index
    pub active_tab: usize,
    /// Broadcast messages in chat tab
    pub messages: VecDeque<String>,
    /// Peer ID of each message sender (None = sent by local user)
    pub message_peer_ids: VecDeque<Option<String>>,
    /// Message IDs for sent messages (None if from other peers)
    pub message_ids: VecDeque<Option<String>>,
    /// Receipt status for broadcast messages: `peer_id` -> (`msg_id` -> timestamp)
    pub broadcast_receipts: HashMap<String, HashMap<String, f64>>,
    /// Known peers
    pub peers: Vec<PeerRecord>,
    /// How many broadcasts *we* sent to each peer (bulk-loaded from
    /// `broadcast_recipients`), driving the peers-table "Broadcast" column.
    pub broadcast_sent_to_peer: HashMap<String, usize>,
    /// Peer IDs currently connected (subset of `peers`)
    pub connected_peer_ids: std::collections::HashSet<String>,
    /// Direct messages per peer
    pub dm_messages: BTreeMap<String, VecDeque<String>>,
    /// Message IDs for DMs per peer
    pub dm_message_ids: BTreeMap<String, VecDeque<Option<String>>>,
    /// DM receipt status per peer: (`source_peer`, timestamp)
    pub dm_receipts: HashMap<String, (String, f64)>,
    /// Current input text in message box
    pub input_text: String,
    /// Logs shown in the debug tab
    pub log_messages: VecDeque<String>,
    /// Whether we're editing a peer's nickname
    pub editing_nickname: bool,
    /// Peer ID being edited (if `editing_nickname` is true)
    pub nickname_peer_id: String,
    /// Whether connected to the network
    pub connected: bool,
    /// Number of connected peers
    pub peer_count: usize,
    /// Whether mouse is captured (for text input)
    pub mouse_capture: bool,
    /// Whether the terminal delivers kitty-keyboard encoding (selects the
    /// Peer-Info shortcut hint: Ctrl+I vs Ctrl+P on a Direct tab)
    pub kitty_keyboard_active: bool,
    /// Optional popup message to display
    pub popup: Option<String>,
    /// Known groups with member counts (for the Groups list tab)
    pub group_summaries: Vec<crate::groups::GroupSummary>,
    /// Group messages per group: formatted display strings
    pub group_messages: BTreeMap<String, VecDeque<String>>,
    /// Message IDs for group messages per group
    pub group_message_ids: BTreeMap<String, VecDeque<Option<String>>>,
    /// Sender peer ID for each group message (None = sent by local user)
    pub group_message_peer_ids: BTreeMap<String, VecDeque<Option<String>>>,
    /// Scroll state per group chat: (offset, `auto_scroll`)
    pub group_scroll_state: BTreeMap<String, (usize, bool)>,
    /// Index of selected group in the Groups list tab
    pub group_selection: usize,
    /// Whether the Groups tab is capturing a group name to create/join
    pub creating_group: bool,
    /// Scroll offset for chat tab
    pub chat_scroll_offset: usize,
    /// Whether chat tab is auto-scrolling to bottom
    pub chat_auto_scroll: bool,
    /// Number of broadcast messages that arrived while not at the bottom
    pub chat_unread_count: usize,
    /// Scroll offset for the log tab
    pub log_scroll_offset: usize,
    /// Whether log tab is auto-scrolling to bottom
    pub log_auto_scroll: bool,
    /// Scroll state per DM peer: (offset, `auto_scroll`)
    pub dm_scroll_state: BTreeMap<String, (usize, bool)>,
    /// Scroll state for DM+broadcast view per peer
    pub dm_broadcast_scroll_state: BTreeMap<String, (usize, bool)>,
    /// Index of selected broadcast message (for receipt popup)
    pub broadcast_selection: Option<usize>,
    /// Index of selected peer in peer list
    pub peer_selection: usize,
    /// Active sort column for the peer list (0=Name,1=DM,2=Broadcast,3=Last Seen,4=First Seen)
    pub peer_sort_column: usize,
    /// Whether the peer list is sorted ascending on the active column
    pub peer_sort_ascending: bool,
    /// First visible row of the peer table (scrolling viewport)
    pub peer_table_offset: usize,
    /// Map of peer ID -> local nickname set for that peer
    pub local_nicknames: HashMap<String, String>,
    /// Map of peer ID -> nickname received/announced by that peer
    pub received_nicknames: HashMap<String, String>,
    /// Current local nickname (for Settings tab)
    pub own_nickname: String,
    /// Local peer ID (for Settings tab)
    pub local_peer_id: String,
    /// Database URL (for Settings tab)
    pub db_url: String,
    /// Platform label, e.g. "Desktop (linux)" (for Settings tab)
    pub platform: String,
    /// Network size classification, e.g. "Small" (for Settings tab)
    pub network_size: String,
    /// Listen addresses reported by the swarm
    pub listen_addrs: Vec<String>,
    /// Epoch seconds of last peer disconnect, if any (for Settings tab)
    pub last_connection_lost: Option<f64>,
    /// Peer ID we last disconnected from, if any (for Settings tab)
    pub last_connection_peer: Option<String>,
    /// Whether the node is running (always true in the TUI)
    pub node_running: bool,
}

